// Generated by Viscosity: "fl" stored as a struct of arrays (fields x, y, vx, vy, hue).
class __Vsc_fl {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); this.y = new Float64Array(cap); this.vx = new Float64Array(cap); this.vy = new Float64Array(cap); this.hue = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_fl(Math.max(16, v.length / 5)); for (let i = 0; i < v.length; i += 5) c.push(v[i + 0], v[i + 1], v[i + 2], v[i + 3], v[i + 4]); return c; }
  push(v0, v1, v2, v3, v4) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; this.y[n] = v1; this.vx[n] = v2; this.vy[n] = v3; this.hue[n] = v4; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; t = new Float64Array(cap); t.set(this.y); this.y = t; t = new Float64Array(cap); t.set(this.vx); this.vx = t; t = new Float64Array(cap); t.set(this.vy); this.vy = t; t = new Float64Array(cap); t.set(this.hue); this.hue = t; }
}
// Boids-style flocking: each boid looks at a window of 64 neighbours.
const N = 20000;
const fl = new __Vsc_fl();
for (let i = 0; i < N; i++) {
  fl.push((i * 13) % 800, (i * 29) % 600, Math.sin(i), Math.cos(i), i % 360);
}
function flock(b) {
  for (let i = 0; i < b.length; i++) {
    let cx = 0;
    let cy = 0;
    for (let j = i + 1; j < i + 64 && j < b.length; j++) {
      cx += b.vx[j];
      cy += b.vy[j];
    }
    b.vx[i] = b.vx[i] * 0.9 + cx * 0.001;
    b.vy[i] = b.vy[i] * 0.9 + cy * 0.001;
  }
  for (let i = 0; i < b.length; i++) {
    b.x[i] += b.vx[i];
    b.y[i] += b.vy[i];
  }
}
const t0 = performance.now();
for (let s = 0; s < 30; s++) flock(fl);
const ms = performance.now() - t0;
let s = 0;
for (let b = 0; b < fl.length; b++) s += fl.x[b] + fl.y[b];
console.log(JSON.stringify({ check: s.toFixed(4), ms }));
